module logic;
use model {Summary,Job};
use util {reverse};

record DependencyScan {pending:List<I64>,ready:Bool}
record JobScan {pending:List<Job>,bestId:I64,bestCost:I64}
record Schedule {done:I64,remaining:I64,order:List<I64>,count:I64,active:Bool}

fn bitFor(jobId:I64)->I64 {
 fold(bitIndex in jobId,weight:I64=1) {weight*2}
}

fn isCompleted(jobId:I64,completed:I64)->Bool {
 (completed/bitFor(jobId))%2==1
}

fn dependenciesReady(dependencies:List<I64>,completed:I64)->Bool {
 let checked=fold(dependencyIndex in List::length(dependencies),dependencyState:DependencyScan=DependencyScan {pending:dependencies,ready:true}) {
  DependencyScan {
   pending:List::tail(dependencyState.pending),
   ready:dependencyState.ready && isCompleted(List::head(dependencyState.pending),completed)
  }
 };
 checked.ready
}

fn chooseJob(jobs:List<Job>,completed:I64,remaining:I64)->JobScan {
 fold(jobIndex in List::length(jobs),scan:JobScan=JobScan {pending:jobs,bestId:24,bestCost:0}) {
  let candidate=List::head(scan.pending);
  if candidate.id<scan.bestId && candidate.cost<=remaining && !isCompleted(candidate.id,completed) && dependenciesReady(candidate.deps,completed) {
   JobScan {pending:List::tail(scan.pending),bestId:candidate.id,bestCost:candidate.cost}
  } else {
   JobScan {...scan,pending:List::tail(scan.pending)}
  }
 }
}

fn run(jobs:List<Job>,budget:I64)->Summary {
 let final=fold(step in List::length(jobs),schedule:Schedule=Schedule {done:0,remaining:budget,order:List::empty<I64>(),count:0,active:true}) {
  if schedule.active {
   let chosen=chooseJob(jobs,schedule.done,schedule.remaining);
   if chosen.bestId<24 {
    Schedule {
     done:schedule.done+bitFor(chosen.bestId),
     remaining:schedule.remaining-chosen.bestCost,
     order:List::prepend(chosen.bestId,schedule.order),
     count:schedule.count+1,
     active:true
    }
   } else {
    Schedule {...schedule,active:false}
   }
  } else {schedule}
 };
 Summary {order:reverse(final.order),spent:budget-final.remaining,blocked:List::length(jobs)-final.count}
}

